        plugin_db_init();
        enable_testing(); // function in wget2 to prevent unwanted action while testing
        init(sizeof(argv)/sizeof(argv[0]), argv);
        deinit();
        plugin_db_finalize(0);
#endif

        config.dont_write = 0;

        return 0;
}
